// Shared script for the per-item share pages p/<id>/index.html (generated by scripts/share_pages.py).
// 2026-11-13: moved out of an inline <script> in every page so the site can run a strict Content-Security-Policy
// (script-src 'self'). Each page passes its own values in <script type="application/json" id="sp-data">.
const D = (() => {
  try {
    return JSON.parse(document.getElementById("sp-data")?.textContent || "{}");
  } catch {
    return {};
  }
})();
(function() {
  let isEn = new URLSearchParams(location.search).get("lang") === "en";
  function applyVoiceLang(lang) {
    const box = document.getElementById("sp-voice-box");
    if (!box) return;
    box.querySelectorAll("[data-sp-vlang]").forEach((b) => {
      b.classList.toggle("active", b.dataset.spVlang === lang);
    });
    const intro = document.getElementById("sp-vb-intro");
    if (intro) intro.textContent = lang === "en" ? intro.dataset.en : intro.dataset.zh;
    const audio = document.getElementById("sp-vb-audio");
    if (audio) {
      const nextSrc = lang === "en" ? audio.dataset.srcEn : audio.dataset.srcZh;
      if (audio.getAttribute("src") !== nextSrc) {
        audio.setAttribute("src", nextSrc);
      }
    }
  }
  function applyPageLang() {
    document.documentElement.lang = isEn ? "en" : "zh-Hant-TW";
    document.querySelectorAll("[data-zh][data-en]").forEach((el) => {
      if (el.id === "sp-vb-intro") return;
      if (el.dataset.zh.includes("<")) el.innerHTML = isEn ? el.dataset.en : el.dataset.zh;
      else el.textContent = isEn ? el.dataset.en : el.dataset.zh;
    });
    const btn = document.getElementById("sp-lang-btn");
    if (btn) btn.textContent = isEn ? "🌐 中文 / EN" : "🌐 EN / 中文";
    const b3d = document.getElementById("sp-btn-3d");
    if (b3d) b3d.href = D.t3d + (isEn ? "&lang=en" : "");
    const b2d = document.getElementById("sp-btn-2d");
    if (b2d) b2d.href = D.t2d + (isEn ? "&lang=en" : "");
    const cHome = document.getElementById("sp-crumb-home");
    if (cHome) cHome.href = isEn ? "../../?lang=en" : "../../";
    const hBrand = document.getElementById("sp-home-brand");
    if (hBrand) hBrand.href = isEn ? "../../?lang=en" : "../../";
    const cIsl = document.getElementById("sp-crumb-isl");
    if (cIsl) cIsl.href = D.tIsland + (isEn ? "&lang=en" : "");
    document.querySelectorAll(".sp-sib").forEach((a) => {
      const base = a.getAttribute("href").split("?")[0];
      a.setAttribute("href", base + (isEn ? "?lang=en" : ""));
    });
    applyVoiceLang(isEn ? "en" : "zh");
    const u = new URL(location.href);
    if (isEn) u.searchParams.set("lang", "en");
    else u.searchParams.delete("lang");
    history.replaceState(null, "", u.pathname + u.search + u.hash);
  }
  document.getElementById("sp-lang-btn")?.addEventListener("click", () => {
    isEn = !isEn;
    applyPageLang();
  });
  document.querySelectorAll("[data-sp-vlang]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const lang = btn.dataset.spVlang;
      applyVoiceLang(lang);
      const audio = document.getElementById("sp-vb-audio");
      if (audio) audio.play().catch(() => {});
    });
  });
  if (isEn) applyPageLang();

  // Auto-stamp this highlight & island into Island Passport (localStorage "htl-passport:v1")
  const PASSPORT_KEY = "htl-passport:v1";
  const STARS = [0, 160, 480, 960, 1600];
  const ITEM_ID = D.id;
  const ISLAND_ID = D.island;
  const TEACHER_ID = D.teacher;
  let gainedNow = 0;

  function loadP() {
    try {
      const o = JSON.parse(localStorage.getItem(PASSPORT_KEY) || "null");
      if (o && o.v === 1) return {
        v: 1,
        islands: Array.isArray(o.islands) ? o.islands : [],
        items: Array.isArray(o.items) ? o.items : [],
        flows: Array.isArray(o.flows) ? o.flows : [],
        teachers: Array.isArray(o.teachers) ? o.teachers : [],
        voices: Array.isArray(o.voices) ? o.voices : [],
        checkins: Array.isArray(o.checkins) ? o.checkins : [],
        chapters: o.chapters && typeof o.chapters === "object" ? o.chapters : {},
        xp: Number(o.xp) || 0,
        badges: o.badges && typeof o.badges === "object" ? o.badges : {},
        counters: o.counters && typeof o.counters === "object" ? o.counters : {},
        soundOn: o.soundOn !== false,
        ...o
      };
    } catch {}
    return { v: 1, islands: [], items: [], flows: [], teachers: [], voices: [], checkins: [], chapters: {}, xp: 0, badges: {}, counters: {}, soundOn: true };
  }
  function saveP(P) {
    try { localStorage.setItem(PASSPORT_KEY, JSON.stringify(P)); } catch {}
  }
  function stampPage(opts = {}) {
    const P = loadP();
    let g = 0;
    if (ITEM_ID && !P.items.includes(ITEM_ID)) { P.items.push(ITEM_ID); g += 10; }
    if (ISLAND_ID && !P.islands.includes(ISLAND_ID)) { P.islands.push(ISLAND_ID); g += 40; }
    if (TEACHER_ID && !P.teachers.includes(TEACHER_ID)) { P.teachers.push(TEACHER_ID); g += 25; }
    if (opts.voice && TEACHER_ID && !P.voices.includes(TEACHER_ID)) { P.voices.push(TEACHER_ID); g += 15; }
    if (opts.source) {
      P.counters = P.counters || {};
      P.counters.source = (P.counters.source || 0) + 1;
      if (P.counters.source === 1) g += 10;
    }
    if (g > 0 || opts.source) {
      P.xp = (Number(P.xp) || 0) + g;
      gainedNow += g;
      saveP(P);
    }
    renderPassportBar(P);
  }
  function renderPassportBar(P) {
    const bar = document.getElementById("sp-passport-bar");
    if (!bar) return;
    let st = 1;
    for (let i = 0; i < STARS.length; i++) if (P.xp >= STARS[i]) st = i + 1;
    const starsStr = "★".repeat(st) + "☆".repeat(5 - st);
    const pHref = isEn ? "../../?passport=1&lang=en" : "../../?passport=1";
    const msg = isEn
      ? `Stamped in Island Passport${gainedNow ? ` (+${gainedNow} XP)` : ""} · ${P.xp} XP · ${P.islands.length}/${D.totalIslands} Islands · ${P.items.length}/${D.totalItems} Highlights`
      : `本頁細項已自動蓋章收入學習護照${gainedNow ? `（+${gainedNow} XP）` : ""} · 累積 ${P.xp} XP · 已蓋章 ${P.islands.length}/${D.totalIslands} 島 · ${P.items.length}/${D.totalItems} 細項`;
    const btnTxt = isEn ? "🛂 Open 3D Passport ↗" : "🛂 開啟 3D 學習護照 ↗";
    bar.innerHTML = `<div class="sp-pb-left"><span class="sp-pb-badge">🛂 PASSPORT</span><span class="sp-pb-stars">${starsStr}</span><span>${msg}</span></div><a class="sp-pb-open" href="${pHref}">${btnTxt}</a>`;
  }
  stampPage();
  document.getElementById("sp-lang-btn")?.addEventListener("click", () => renderPassportBar(loadP()));
  document.getElementById("sp-vb-audio")?.addEventListener("play", () => stampPage({ voice: true }));
  document.querySelectorAll(".sp-source-btn").forEach((a) => a.addEventListener("click", () => stampPage({ source: true })));
})();
